export { default as Tooltip } from "./Tooltip.vue";
export { default as TooltipContent } from "./TooltipContent.vue";
export { default as TooltipTrigger } from "./TooltipTrigger.vue";
export type * from "./types.ts";

@layer components {
  /* Tooltip: ui-sdk's stylesheet draws the inverted box. This keeps a long text short and readable. */
  [data-slot="tooltip-content"] {
    border-radius: calc(var(--vh-radius) * 0.75);
    font-size: 0.75rem;
    line-height: 1rem;
    max-width: 20rem;
    text-wrap: balance;
  }
}

export type TooltipSide = "top" | "right" | "bottom" | "left";

export interface TooltipProps {
  open?: boolean;
  defaultOpen?: boolean;
  delay?: number;
  label?: string;
}

export interface TooltipEmits {
  "update:open": [open: boolean];
}

export interface TooltipSlots {
  default?: () => unknown;
}

export interface TooltipContentProps {
  side?: TooltipSide;
  sideOffset?: number;
}

export interface TooltipTriggerSlots {
  default?: () => unknown;
}

export interface TooltipContentSlots {
  default?: () => unknown;
}
